import heapq


def dependency_solver(data, name_order, preference):
    packages = data["packages"]
    names = sorted(packages, reverse=(name_order == "descending"))
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    choices = [[-1] + [row["version"] for row in packages[name]]
               for name in names]
    best = None
    best_versions = None

    for vector in product(*choices):
        selected = dict(zip(names, vector))
        installed = {name for name, version in selected.items() if version != -1}
        valid = True
        for name, bounds in data["roots"].items():
            version = selected[name]
            if version == -1 or not bounds[0] <= version <= bounds[1]:
                valid = False
                break
        if not valid:
            continue

        edges = {name: [] for name in installed}
        for name in installed:
            version = selected[name]
            if version in blocked.get(name, []) or (name in pins and version != pins[name]):
                valid = False
                break
            row = next(row for row in packages[name] if row["version"] == version)
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                ov = selected[other]
                if ov == -1 or not dep["min"] <= ov <= dep["max"]:
                    valid = False
                    break
                edges[name].append(other)
            if not valid:
                break
        if not valid:
            continue

        # The installation must be exactly the roots' dependency closure.
        reached = set()
        stack = list(data["roots"])
        while stack:
            name = stack.pop()
            if name in reached:
                continue
            reached.add(name)
            stack.extend(edges[name])
        if reached != installed:
            continue

        # Reject directed cycles, including self-loops.
        state = {}
        def acyclic(name):
            if state.get(name) == 1:
                return False
            if state.get(name) == 2:
                return True
            state[name] = 1
            for other in edges[name]:
                if not acyclic(other):
                    return False
            state[name] = 2
            return True
        if not all(acyclic(name) for name in installed):
            continue

        if best is None or (vector < best if preference == "minimum" else vector > best):
            best = vector
            best_versions = {name: version for name, version in selected.items()
                             if version != -1}

    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}


def ledger(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for pos, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        key = (sequence, event.get("revision", 0), pos)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    def rounded(n, d):
        if mode == "half_up":
            return (2 * n + d) // (2 * d)
        return n // d

    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000)
        tax = rounded(raw * event.get("tax_bp", 0), 10000)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        account = event.get("account", "default")
        currency = event.get("currency", "USD")
        key = account + "|" + currency
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def quota_intervals(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None
    for subset in combinations([j for j in jobs if j["id"] not in blocked], k):
        ids = sorted(j["id"] for j in subset)
        if not mandatory.issubset(ids):
            continue
        ordered = sorted(subset, key=lambda j: (j["start"], j["end"], j["id"]))
        if any(ordered[i]["end"] > ordered[i + 1]["start"]
               for i in range(len(ordered) - 1)):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        value = sum(j["value"] for j in subset)
        if (best_value is None or value > best_value or
                (value == best_value and ids > best_ids)):
            best_value, best_ids = value, ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def temporal_routes(data):
    required = data.get("required", [])
    indices = {node: i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    initial_mask = 1 << indices[source] if source in indices else 0
    start_state = (source, initial_mask, 0)
    distances = {start_state: data["start"]}
    queue = [(data["start"], source, initial_mask, 0)]
    while queue:
        time, node, mask, used = heapq.heappop(queue)
        state = (node, mask, used)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full and used == data["coupons"]:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            durations = [edge["duration"]]
            if used < data["coupons"]:
                durations.append(max(1, edge["duration"] - edge.get("discount", 0)))
            for choice, duration in enumerate(durations):
                next_used = used + (1 if choice else 0)
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                nxt = edge["v"]
                next_mask = mask | ((1 << indices[nxt]) if nxt in indices else 0)
                next_state = (nxt, next_mask, next_used)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, nxt, next_mask, next_used))
    return {"arrival": None}


